{
  "name": "gyoshu",
  "version": "0.4.33",
  "description": "Scientific research agent extension for OpenCode - turns research goals into reproducible Jupyter notebooks",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "bin": {
    "gyoshu": "./bin/gyoshu.js"
  },
  "files": [
    "src/",
    "bin/"
  ],
  "scripts": {
    "test": "bun test ./tests",
    "test:watch": "bun test --watch ./tests",
    "test:python": "pytest tests/test_bridge.py -v"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Yeachan-Heo/My-Jogyo.git"
  },
  "homepage": "https://github.com/Yeachan-Heo/My-Jogyo#readme",
  "bugs": {
    "url": "https://github.com/Yeachan-Heo/My-Jogyo/issues"
  },
  "author": "Yeachan Heo",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "research",
    "scientific",
    "jupyter",
    "repl",
    "data-science",
    "machine-learning",
    "ai-agent",
    "automation",
    "notebook"
  ],
  "engines": {
    "bun": ">=1.0.0"
  },
  "os": [
    "darwin",
    "linux"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "@types/sanitize-html": "^2.16.0",
    "bun-types": "latest"
  },
  "dependencies": {
    "sanitize-html": "^2.17.0",
    "zod": "^3.23.0"
  }
}
